      {
        "selector": "ChatComposerDrawer",
        "status": "found",
        "result": {
          "type": "component.detail",
          "package": "@astryxdesign/core",
          "data": {
            "name": "ChatComposerDrawer",
            "subComponentOf": "Chat",
            "displayName": "Chat Composer Drawer",
            "isHiddenFromOverview": true,
            "description": "Collapsible drawer panel that sits above the chat input inside ChatComposer. Pass it to the composer's `drawer` slot to show attachments, context chips, or any supplementary content. When `count` is provided the drawer gains a collapse toggle: collapsed state shows the default Badge and label or caller-provided `collapsedSummary`, while expanded state shows all children.",
            "usage": {
              "description": "Use ChatComposerDrawer in the ChatComposer drawer slot for supplementary content such as attachments, context chips, or previews. Provide count only when people should be able to collapse that content.",
              "bestPractices": [
                {
                  "guidance": true,
                  "description": "Give label a concrete plural noun such as \"Attachments\" so the expand and collapse actions have a useful accessible name."
                },
                {
                  "guidance": true,
                  "description": "Use controlled isCollapsed with onCollapsedChange when another part of the page owns drawer state; otherwise use defaultIsCollapsed."
                },
                {
                  "guidance": false,
                  "description": "Put primary composer actions in the drawer; use ChatComposer footer or send-action slots so those controls remain available when the drawer is collapsed."
                }
              ],
              "anatomy": [
                {
                  "name": "Root surface",
                  "required": true,
                  "description": "The drawer surface that composes above the ChatComposer body."
                },
                {
                  "name": "Disclosure toggle",
                  "required": false,
                  "description": "The keyboard- and pointer-operable collapse control rendered when count is provided."
                },
                {
                  "name": "Collapsed summary",
                  "required": false,
                  "description": "The default count Badge and label, or caller-provided visual content, presented while the drawer is collapsed."
                },
                {
                  "name": "Content area",
                  "required": true,
                  "description": "The caller-provided supplementary content; collapsed descendants are unavailable to keyboard and assistive technology."
                }
              ]
            },
            "theming": {
              "targets": [
                {
                  "className": "astryx-chat-composer-drawer",
                  "visualProps": [
                    "collapsed"
                  ]
                }
              ]
            },
            "playground": {
              "wrapper": {
                "component": "Stack",
                "props": {
                  "width": 480
                }
              },
              "defaults": {
                "count": 3,
                "label": "Attachments",
                "children": [
                  {
                    "__element": "Token",
                    "props": {
                      "label": "design-spec.pdf"
                    }
                  },
                  {
                    "__element": "Token",
                    "props": {
                      "label": "api-schema.json"
                    }
                  },
                  {
                    "__element": "Token",
                    "props": {
                      "label": "screenshot.png"
                    }
                  }
                ]
              }
            },
            "props": [
              {
                "name": "children",
                "type": "ReactNode",
                "description": "Content to render inside the drawer: tokens, chips, previews, or any React elements.",
                "required": true
              },
              {
                "name": "count",
                "type": "number",
                "description": "Total item count shown in the collapsed badge. When provided, the drawer gains a collapse/expand toggle."
              },
              {
                "name": "label",
                "type": "string",
                "description": "Label shown next to the count in the default collapsed summary and used to name the expand/collapse action.",
                "default": "'Items'"
              },
              {
                "name": "collapsedSummary",
                "type": "ReactNode",
                "description": "Visual content for the complete Collapsed summary anatomy part. When count enables collapse, this replaces the default neutral Badge and label while the component retains disclosure behavior and accessible naming."
              },
              {
                "name": "isCollapsed",
                "type": "boolean",
                "description": "Controlled collapsed state. Use with `onCollapsedChange` for external control."
              },
              {
                "name": "defaultIsCollapsed",
                "type": "boolean",
                "description": "Initial collapsed state for uncontrolled usage.",
                "default": "false"
              },
              {
                "name": "onCollapsedChange",
                "type": "(isCollapsed: boolean) => void",
                "description": "Callback fired when the user toggles the drawer."
              }
            ],
            "package": "@astryxdesign/core",
            "import": "@astryxdesign/core/Chat",
            "sourceAvailable": true
          }
        }
      },
      {
        "selector": "ChatComposerInput",
        "status": "found",
        "result": {
          "type": "component.detail",
          "package": "@astryxdesign/core",
          "data": {
            "name": "ChatComposerInput",
            "subComponentOf": "Chat",
            "displayName": "Chat Composer Input",
            "isHiddenFromOverview": true,
            "description": "Rich text input for the chat composer. Supports trigger menus (type @ or / to open a typeahead), inline tokens rendered as badges, message history recall with ArrowUp/Down, paste/drop file handling, and a 16px iOS font-size floor to prevent input zoom. Pass it to ChatComposer's input slot when you need more than a plain textarea.",
            "usage": {
              "description": "Pass ChatComposerInput to ChatComposer's input slot when the draft needs trigger menus, inline tokens, history recall, dictation insertion, or file intake.",
              "bestPractices": [
                {
                  "guidance": true,
                  "description": "Use handleRef for programmatic text or token insertion; inserted text follows the same onChange pipeline as typing."
                },
                {
                  "guidance": true,
                  "description": "Use onFiles for files pasted or dropped onto the editor, and keep file validation and upload progress in the product layer."
                },
                {
                  "guidance": false,
                  "description": "Use custom token rendering for ordinary mentions or commands; prefer the structured badge form so tokens remain predictable and themeable."
                }
              ],
              "anatomy": [
                {
                  "name": "Input root",
                  "required": true,
                  "description": "The themed container that forwards the root ref and BaseProps styling seams."
                },
                {
                  "name": "Editable surface",
                  "required": true,
                  "description": "The labeled contenteditable textbox or combobox that owns text, selection, keyboard, paste, and drop behavior."
                },
                {
                  "name": "Placeholder",
                  "required": false,
                  "description": "Visual guidance shown only while the serialized draft is empty."
                },
                {
                  "name": "Trigger menu",
                  "required": false,
                  "description": "The suggestion popup rendered while a configured trigger is active."
                },
                {
                  "name": "Inline token",
                  "required": false,
                  "description": "A non-editable badge or custom rendering with a stable serialized value."
                }
              ]
            },
            "props": [
              {
                "name": "handleRef",
                "type": "React.Ref<ChatComposerInputHandle>",
                "description": "Imperative handle for programmatic control: insertToken, expandToken, insertText, focus, and getValue."
              },
              {
                "name": "value",
                "type": "string",
                "description": "Controlled input value. Pair with onChange for two-way binding."
              },
              {
                "name": "onChange",
                "type": "(value: string) => void",
                "description": "Called when the input value changes. The serialized string includes token placeholders."
              },
              {
                "name": "placeholder",
                "type": "string",
                "description": "Placeholder text shown when the input is empty.",
                "default": "'Type a message...'"
              },
              {
                "name": "maxRows",
                "type": "number",
                "description": "Maximum visible rows before the input scrolls. Use a lower value in compact layouts.",
                "default": "8"
              },
              {
                "name": "triggers",
                "type": "ChatComposerTrigger[]",
                "description": "Trigger definitions for typeahead menus. Each trigger specifies a character (@ or /), a search source, and an onSelect handler that returns the token to insert. Set hasMultiWordQuery: true when suggestions contain spaces (people, topics): the query then runs to a line break or about 64 characters instead of ending at the first space. Per-trigger emptySearchText (ReactNode) is the message when the query matched nothing."
              },
              {
                "name": "debounceMs",
                "type": "number",
                "description": "Debounce delay for async search sources to avoid excessive network requests.",
                "default": "150"
              },
              {
                "name": "hasHistory",
                "type": "boolean",
                "description": "Enable ArrowUp/Down to recall previously submitted messages.",
                "default": "true"
              },
              {
                "name": "label",
                "type": "string",
                "description": "Accessible label announced by screen readers.",
                "default": "'Message input'"
              },
              {
                "name": "isDisabled",
                "type": "boolean",
                "description": "Disables the input. Use during streaming or when a prerequisite is unmet.",
                "default": "false"
              },
              {
                "name": "onPaste",
                "type": "(event, text) => boolean | void",
                "description": "Called when plain text is pasted. Return true after handling the text yourself; otherwise ChatComposerInput inserts it or applies paste-as-token behavior."
              },
              {
                "name": "pasteAsToken",
                "type": "UseChatPasteAsTokenReturn | false",
                "description": "Paste-as-token behavior. By default, plain-text pastes over 200 characters become expandable tokens. Pass false to keep every text paste inline, or provide useChatPasteAsToken() to customize the conversion."
              },
              {
                "name": "onFiles",
                "type": "(files: File[]) => void",
                "description": "Called when files are pasted or dropped onto the input. Use to handle attachments."
              },
              {
                "name": "onSubmit",
                "type": "(value: string) => void",
                "description": "Called when the user presses Enter without Shift. The serialized value includes token placeholders."
              },
              {
                "name": "onKeyDown",
                "type": "(event) => void",
                "description": "Key-down handler invoked before the built-in Enter/history behavior (after any open trigger menu). The seam for platform-specific keys: call event.preventDefault() to suppress the default submit (e.g. newline on a touch keyboard), or act on the event yourself to add behavior (e.g. submit on Cmd/Ctrl+Enter). IME composition is always respected; Enter never submits mid-composition."
              },
              {
                "name": "enterKeyHint",
                "type": "'enter' | 'done' | 'go' | 'next' | 'previous' | 'search' | 'send'",
                "description": "What the Return key of a touch keyboard says (the native enterkeyhint). Enter sends the message, so it defaults to send and iOS shows its Send key. When onKeyDown makes Enter insert a line break on touch keyboards, pass enter so the key shows Return again.",
                "default": "'send'"
              }
            ],
            "package": "@astryxdesign/core",
            "import": "@astryxdesign/core/Chat",
            "sourceAvailable": true
          }
        }
      },
      {
        "selector": "ChatDictationButton",
        "status": "found",
        "result": {
          "type": "component.detail",
          "package": "@astryxdesign/core",
          "data": {
            "name": "ChatDictationButton",
            "displayName": "Chat Dictation Button",
            "group": "Chat",
            "category": "Chat",
            "isHiddenFromOverview": true,
            "hidden": false,
            "keywords": [
              "dictation",
              "microphone",
              "voice",
              "speech",
              "recording",
              "stt",
              "speech-to-text",
              "voice-input",
              "mic"
            ],
            "usage": {
              "description": "ChatDictationButton is a toggle button that starts and stops voice dictation inside a chat composer. It pairs with useChatDictation to show a microphone icon when idle and animated frequency bars when listening. Place it in the sendActions slot of ChatComposer.",
              "bestPractices": [
                {
                  "guidance": true,
                  "description": "Place the dictation button in the sendActions slot of ChatComposer so it sits next to the send button where users expect voice input controls."
                },
                {
                  "guidance": true,
                  "description": "Pass an inputRef to useChatDictation so interim transcripts appear as ghost text in the composer input while the user speaks."
                },
                {
                  "guidance": true,
                  "description": "Enable hasSounds on useChatDictation to give users audio feedback when dictation starts and stops. This is especially helpful when the button's visual change is subtle."
                },
                {
                  "guidance": false,
                  "description": "Don't use the dictation button outside a chat composer context. It's designed for the composer's send-action layout, not as a standalone recording control."
                },
                {
                  "guidance": false,
                  "description": "Don't forget to handle the unsupported case. The button hides itself by default when the browser lacks SpeechRecognition, but you should still design the composer to work without it."
                }
              ],
              "anatomy": [
                {
                  "name": "Microphone icon",
                  "required": true,
                  "description": "Shown in the idle state. Indicates that tapping will start voice input."
                },
                {
                  "name": "Frequency bars",
                  "required": false,
                  "description": "Animated equalizer bars that replace the icon during listening. React to real microphone volume."
                },
                {
                  "name": "Ghost button",
                  "required": true,
                  "description": "The underlying Button with ghost variant and isIconOnly, providing the hit target and focus ring."
                }
              ]
            },
            "props": [
              {
                "name": "dictation",
                "type": "UseSpeechRecognitionReturn",
                "description": "The return value from useChatDictation or useSpeechRecognition. Controls all button state: listening, volume, bands, and toggle.",
                "required": true
              },
              {
                "name": "size",
                "type": "'sm' | 'md'",
                "description": "Button size. Matches ChatComposer density.",
                "default": "'md'"
              },
              {
                "name": "isHiddenWhenUnsupported",
                "type": "boolean",
                "description": "When true, renders nothing if the browser does not support SpeechRecognition. When false, keeps the button visible but disabled.",
                "default": "true"
              },
              {
                "name": "label",
                "type": "string",
                "description": "Accessible label override. Defaults to \"Start dictation\" or \"Stop dictation\" based on state."
              },
              {
                "name": "xstyle",
                "type": "StyleXStyles",
                "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value, not an inline style object like style={{}}."
              }
            ],
            "package": "@astryxdesign/core",
            "import": "@astryxdesign/core/Chat",
            "sourceAvailable": true
          }
        }
      }
    ]
  },
  "meta": {
